//
// 목표: 10개 언어를 하나의 통합 시스템으로 연결하기 위한 기본 인터페이스 정의
//
// 참고: FreeLang (자체 언어로 작성) 기반 통합 계층
//

// ============================================================================
// 1. 토큰 및 렉싱 (Lexing)
// ============================================================================

record Token =
  token_type: String,     // "keyword", "identifier", "number", "string", "operator", "punctuation"
  lexeme: String,         // 실제 텍스트
  line: Int,
  column: Int,
  value: Option[String]   // 리터럴의 경우 해석된 값

