  // 출력: 토큰 배열 또는 에러 메시지
  Result::Err("tokenize not implemented")

// ============================================================================
// 2. 파싱 (Parsing)
// ============================================================================

record ASTNode =
  node_type: String,          // "program", "function", "expression", "statement", etc.
  name: Option[String],        // 함수명, 변수명 등
  value: Option[String],       // 리터럴 값
  node_type_info: Option[String], // 타입 정보
  children: Array[ASTNode]    // 자식 노드들

// Parser 인터페이스
function parse(tokens: Array[Token]): Result[ASTNode, String] =
  // 입력: 토큰 배열
  // 출력: AST 루트 노드 또는 에러 메시지
  Result::Err("parse not implemented")

// ============================================================================
// 3. 타입 검사 (Type Checking)
// ============================================================================

record TypeInfo =
  base_type: String,          // "int", "float", "string", "bool", "array", "function", "record", "void"
  is_nullable: Bool,
  is_array: Bool,
  array_element_type: Option[String],
  function_params: Option[Array[String]],  // 함수의 파라미터 타입
  function_return_type: Option[String],     // 함수의 반환 타입
  record_fields: Option[Array[String]]      // 레코드의 필드 타입

record TypeContext =
  program: ASTNode,
  variables: Array[String],   // 정의된 변수 목록
  functions: Array[String],   // 정의된 함수 목록
  type_map: Array[String],    // 타입 정보 (변수명 -> 타입)
  errors: Array[String]       // 타입 에러 목록

// Type Checker 인터페이스
function type_check(ast: ASTNode): Result[TypeContext, String] =
  // 입력: AST 노드
  // 출력: 타입 정보 포함 컨텍스트 또는 에러
  Result::Err("type_check not implemented")

// ============================================================================
// 4. 중간 표현 (IR - Intermediate Representation)
// ============================================================================

record IRInstruction =
  opcode: String,             // "mov", "add", "call", "ret", "jmp", etc.
  operands: Array[String],    // 피연산자 (변수, 상수, 레이블)
  result: Option[String]      // 결과 저장 위치

record IRModule =
  name: String,
  instructions: Array[IRInstruction],
  data_section: Array[String],      // 전역 데이터
  symbol_table: Array[String],      // 심볼 테이블
  debug_info: Array[String]         // 디버그 정보

// IR Builder 인터페이스
function build_ir(ast: ASTNode): Result[IRModule, String] =
  // 입력: 타입 검사된 AST
  // 출력: 중간 표현 또는 에러
  Result::Err("build_ir not implemented")

// ============================================================================
// 5. 코드 생성 (Code Generation)
// ============================================================================

record GeneratedCode =
  language: String,           // "c", "go", "wasm", "x86", etc.
  code: String,               // 생성된 코드
  includes: Array[String],    // 필요한 헤더/import
  size_bytes: Int,            // 코드 크기 (바이트)
  has_main: Bool              // main 함수 포함 여부

// Code Generator 인터페이스
function generate_code(ir: IRModule, target_language: String): Result[GeneratedCode, String] =
  // 입력: 중간 표현 + 대상 언어
  // 출력: 생성된 코드 또는 에러
  Result::Err("generate_code not implemented")

// ============================================================================
// 6. 런타임 (Runtime Execution)
// ============================================================================

record ExecutionContext =
  program_name: String,
  variables: Array[String],        // 실행 중 변수 값
  call_stack: Array[String],       // 호출 스택
  return_value: Option[String],    // 마지막 반환값
  exit_code: Int,                  // 프로그램 종료 코드
  error_message: Option[String]    // 실행 중 에러

// Runtime 인터페이스
function execute(code: GeneratedCode): Result[ExecutionContext, String] =
  // 입력: 생성된 코드
  // 출력: 실행 결과 또는 에러
  Result::Err("execute not implemented")

// ============================================================================
// 7. 통합 컴파일러 파이프라인
// ============================================================================

record CompilerState =
  source: String,
  source_language: String,        // "freelang", "fv", "go", "wasm"
  target_language: String,        // 생성할 코드의 언어
  tokens: Array[Token],
  ast: Option[ASTNode],
  type_context: Option[TypeContext],
  ir: Option[IRModule],
  generated_code: Option[GeneratedCode],
  execution_result: Option[ExecutionContext],
  errors: Array[String],
  warnings: Array[String]

// 통합 컴파일 함수: 소스 → AST → IR → 코드 생성 → 실행
function compile_and_run(
  source: String,
  source_language: String,
  target_language: String
): Result[ExecutionContext, String] =
  // Step 1: Tokenize
  let tokens_result = tokenize(source)
  match tokens_result
    case Result::Err(e) -> Result::Err("Tokenize error: " ++ e)
    case Result::Ok(tokens) ->
      // Step 2: Parse
      let parse_result = parse(tokens)
      match parse_result
        case Result::Err(e) -> Result::Err("Parse error: " ++ e)
        case Result::Ok(ast) ->
          // Step 3: Type Check
          let type_result = type_check(ast)
          match type_result
            case Result::Err(e) -> Result::Err("Type check error: " ++ e)
            case Result::Ok(type_ctx) ->
              // Step 4: Build IR
              let ir_result = build_ir(ast)
              match ir_result
                case Result::Err(e) -> Result::Err("IR build error: " ++ e)
                case Result::Ok(ir) ->
                  // Step 5: Generate Code
                  let gen_result = generate_code(ir, target_language)
                  match gen_result
                    case Result::Err(e) -> Result::Err("Code gen error: " ++ e)
                    case Result::Ok(code) ->
                      // Step 6: Execute
                      let exec_result = execute(code)
                      exec_result
                    end
                  end
                end
              end
            end
        end
    end

// ============================================================================
// 8. 언어 간 타입 호환성 매핑
// ============================================================================

record TypeMapping =
  freelang_type: String,      // FreeLang 타입
  go_type: String,            // Go 타입
  c_type: String,             // C 타입
  wasm_type: String,          // WASM 타입
  fv_type: String             // FV 타입
  // 추가 언어 타입들...

// 모든 언어의 기본 타입 매핑 테이블
function get_type_mapping(freelang_type: String): Option[TypeMapping] =
  match freelang_type
    // 정수형
    case "Int" ->
      Option::Some(TypeMapping(
        freelang_type="Int",
        go_type="int64",
        c_type="long long",
        wasm_type="i64",
        fv_type="i64"
      ))
    // 부동소수형
    case "Float" ->
      Option::Some(TypeMapping(
        freelang_type="Float",
        go_type="float64",
        c_type="double",
        wasm_type="f64",
        fv_type="f64"
      ))
    // 문자열
    case "String" ->
      Option::Some(TypeMapping(
        freelang_type="String",
        go_type="string",
        c_type="char*",
        wasm_type="i32",  // 메모리 오프셋
        fv_type="str"
      ))
    // 불린
    case "Bool" ->
      Option::Some(TypeMapping(
        freelang_type="Bool",
        go_type="bool",
        c_type="int",
        wasm_type="i32",
        fv_type="bool"
      ))
    // 배열
    case "Array" ->
      Option::Some(TypeMapping(
        freelang_type="Array",
        go_type="[]T",
        c_type="T*",
        wasm_type="i32",  // 메모리 오프셋
        fv_type="arr"
      ))
    // 딕셔너리
    case "Dict" ->
      Option::Some(TypeMapping(
        freelang_type="Dict",
        go_type="map[K]V",
        c_type="hashtable_t",
        wasm_type="i32",  // 메모리 오프셋
        fv_type="dict"
      ))
    // 함수
    case "Function" ->
      Option::Some(TypeMapping(
        freelang_type="Function",
        go_type="func(...) ...",
        c_type="(*)()",
        wasm_type="i32",  // 함수 인덱스
        fv_type="fn"
      ))
    // Unit/Void
    case "Unit" ->
      Option::Some(TypeMapping(
        freelang_type="Unit",
        go_type="",
        c_type="void",
        wasm_type="void",
        fv_type="()"
      ))
    case _ -> Option::None
  end

// ============================================================================
// 9. FFI (Foreign Function Interface) 정의
// ============================================================================

record FFIBinding =
  source_language: String,
  source_function: String,    // 함수명
  target_language: String,
  target_function: String,    // 호출할 함수명
  parameter_mapping: Array[String],   // 파라미터 타입 변환
  return_mapping: String      // 반환 타입 변환

// FFI 자동 생성 함수
function generate_ffi_binding(
  from_lang: String,
  from_fn: String,
  to_lang: String,
  to_fn: String
): Result[String, String] =
  // 입력: 소스 언어/함수, 대상 언어/함수
  // 출력: FFI 브릿지 코드 또는 에러
  Result::Err("FFI generation not implemented")

// ============================================================================
// 10. 통합 시스템 메트릭
// ============================================================================

record CompileMetrics =
  source_lines: Int,
  tokens_count: Int,
  ast_nodes: Int,
  ir_instructions: Int,
  generated_code_size: Int,
  compile_time_ms: Int,
  execution_time_ms: Int,
  memory_used_bytes: Int

// ============================================================================
// 테스트: 공통 인터페이스가 제대로 정의되었는지 확인
// ============================================================================

function test_interface_definition(): Bool =
  // 이 함수가 컴파일되면, 모든 record와 function 서명이 올바르게 정의된 것
  true

// 실행
function main(): Unit =
  let result = test_interface_definition()
  match result
    case true -> println("✅ Common interface definition: OK")
    case false -> println("❌ Common interface definition: FAILED")
  end

