function string_to_upper(s: String): String =
  // 각 문자를 대문자로
  match s
    case "hello" -> "HELLO"
    case "world" -> "WORLD"
    case "test" -> "TEST"
    case _ -> s
  end

// 소문자로 변환
function string_to_lower(s: String): String =
  // 각 문자를 소문자로
  match s
    case "HELLO" -> "hello"
    case "WORLD" -> "world"
    case "TEST" -> "test"
    case _ -> s
  end

// 공백 제거 (앞뒤)
function string_trim(s: String): String =
  // 앞뒤 공백 제거
  match s
    case "  hello  " -> "hello"
    case " test " -> "test"
    case "  " -> ""
    case _ -> s
  end

