	"fmt"
	"strings"
)

// ============================================================================
// 1. 기본 문자열 연산
// ============================================================================

// 문자열 길이
func stringLength(s string) int {
	return len(s)
}

// 두 문자열 연결
func stringConcat(s1, s2 string) string {
	return s1 + s2
}

// 문자열 비교
func stringEquals(s1, s2 string) bool {
	return s1 == s2
}

// 문자열이 비어있는지 확인
func stringIsEmpty(s string) bool {
	return len(s) == 0
}

// ============================================================================
// 2. 문자열 부분 추출
// ============================================================================

// 부분 문자열 추출 (start부터 end까지)
// substring("Hello", 0, 5) = "Hello"
func stringSubstring(s string, start, end int) string {
	if start < 0 || end > len(s) || start > end {
		return ""
	}
	return s[start:end]
}

// 특정 인덱스의 문자 반환
func stringCharAt(s string, index int) string {
	if index < 0 || index >= len(s) {
		return ""
	}
	return string(s[index])
}

// ============================================================================
// 3. 문자열 검색
// ============================================================================

// 부분 문자열 포함 확인
func stringContains(s, substring string) bool {
	return strings.Contains(s, substring)
}

// 부분 문자열의 인덱스 반환 (-1이면 없음)
func stringIndexOf(s, substring string) int {
	return strings.Index(s, substring)
}

// 문자열 시작 확인
func stringStartsWith(s, prefix string) bool {
	return strings.HasPrefix(s, prefix)
}

// 문자열 종료 확인
func stringEndsWith(s, suffix string) bool {
	return strings.HasSuffix(s, suffix)
}

// ============================================================================
// 4. 문자열 변환
// ============================================================================

// 대문자로 변환
func stringToUpper(s string) string {
	return strings.ToUpper(s)
}

// 소문자로 변환
func stringToLower(s string) string {
	return strings.ToLower(s)
}

// 공백 제거 (앞뒤)
func stringTrim(s string) string {
	return strings.TrimSpace(s)
}

// ============================================================================
// 5. 문자열 분할
// ============================================================================

// 문자열을 구분자로 분할
func stringSplit(s, delimiter string) []string {
	if len(delimiter) == 0 {
		return []string{s}
	}
	return strings.Split(s, delimiter)
}

// ============================================================================
// 6. 문자열 치환
// ============================================================================

// 모든 발생을 치환
func stringReplace(s, find, replace string) string {
	return strings.ReplaceAll(s, find, replace)
}

// ============================================================================
// 7. 문자열 반복
// ============================================================================

// 문자열 반복
func stringRepeat(s string, count int) string {
	return strings.Repeat(s, count)
}

// ============================================================================
// 8. 추가 유틸리티
// ============================================================================

// 첫 n개 글자
func stringPrefix(s string, n int) string {
	if n > len(s) {
		return s
	}
	return s[:n]
}

// 마지막 n개 글자
func stringSuffix(s string, n int) string {
	if n > len(s) {
		return s
	}
	return s[len(s)-n:]
}

// 단어 개수 (공백 기준)
func stringWordCount(s string) int {
	return len(strings.Fields(s))
}

