// String Operations - C Version
//
// 목표: FreeLang-to-C 트랜스파일러의 문자열 처리 검증
// 특징: C 표준 라이브러리 (string.h) 활용

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define MAX_STRING_LEN 256

// ============================================================================
// 1. 기본 문자열 연산
// ============================================================================

// 문자열 길이
int string_length(const char *s) {
    return strlen(s);
}

// 두 문자열 연결
char *string_concat(const char *s1, const char *s2) {
    static char result[MAX_STRING_LEN];
    strcpy(result, s1);
    strcat(result, s2);
    return result;
}

// 문자열 비교
int string_equals(const char *s1, const char *s2) {
    return strcmp(s1, s2) == 0;
}

// 문자열이 비어있는지 확인
int string_is_empty(const char *s) {
    return strlen(s) == 0;
}

// ============================================================================
// 2. 문자열 부분 추출
// ============================================================================

// 부분 문자열 추출 (start부터 end까지)
char *string_substring(const char *s, int start, int end) {
    static char result[MAX_STRING_LEN];
    int len = end - start;

    if (start < 0 || end > (int)strlen(s) || start > end || len <= 0) {
        return "";
    }

    strncpy(result, &s[start], len);
    result[len] = '\0';
    return result;
}

// 특정 인덱스의 문자 반환
char *string_char_at(const char *s, int index) {
    static char result[2];

    if (index < 0 || index >= (int)strlen(s)) {
        return "";
    }

    result[0] = s[index];
    result[1] = '\0';
    return result;
}

// ============================================================================
// 3. 문자열 검색
// ============================================================================

// 부분 문자열 포함 확인
int string_contains(const char *s, const char *substring) {
    return strstr(s, substring) != NULL;
}

// 부분 문자열의 인덱스 반환 (-1이면 없음)
int string_index_of(const char *s, const char *substring) {
    const char *pos = strstr(s, substring);
    if (pos == NULL) {
        return -1;
    }
    return pos - s;
}

// 문자열 시작 확인
int string_starts_with(const char *s, const char *prefix) {
    return strncmp(s, prefix, strlen(prefix)) == 0;
}

// 문자열 종료 확인
int string_ends_with(const char *s, const char *suffix) {
    int s_len = strlen(s);
    int suffix_len = strlen(suffix);

    if (suffix_len > s_len) {
        return 0;
    }

    return strcmp(&s[s_len - suffix_len], suffix) == 0;
}

// ============================================================================
// 4. 문자열 변환
// ============================================================================

// 대문자로 변환
char *string_to_upper(const char *s) {
    static char result[MAX_STRING_LEN];
    strcpy(result, s);

    for (int i = 0; result[i]; i++) {
        result[i] = toupper((unsigned char)result[i]);
    }

    return result;
}

// 소문자로 변환
char *string_to_lower(const char *s) {
    static char result[MAX_STRING_LEN];
    strcpy(result, s);

    for (int i = 0; result[i]; i++) {
        result[i] = tolower((unsigned char)result[i]);
    }

    return result;
}

// 공백 제거 (앞뒤)
char *string_trim(const char *s) {
    static char result[MAX_STRING_LEN];
    int start = 0, end = strlen(s) - 1;

    // 앞의 공백 제거
    while (start <= end && isspace((unsigned char)s[start])) {
        start++;
    }

    // 뒤의 공백 제거
    while (end >= start && isspace((unsigned char)s[end])) {
        end--;
    }

    int len = end - start + 1;
    if (len <= 0) {
        result[0] = '\0';
    } else {
        strncpy(result, &s[start], len);
        result[len] = '\0';
    }

    return result;
}

// ============================================================================
// 5. 문자열 분할
// ============================================================================

// 문자열을 구분자로 분할 (배열로 반환)
// 반환값: 분할된 부분의 개수
int string_split(const char *s, const char *delimiter, char **parts) {
    char temp[MAX_STRING_LEN];
    strcpy(temp, s);

    int count = 0;
    char *token = strtok(temp, delimiter);

    while (token != NULL && count < 10) {
        parts[count] = (char *)malloc(strlen(token) + 1);
        strcpy(parts[count], token);
        count++;
        token = strtok(NULL, delimiter);
    }

    return count;
}

// ============================================================================
// 6. 문자열 치환
// ============================================================================

// 모든 발생을 치환
char *string_replace(const char *s, const char *find, const char *replace_str) {
    static char result[MAX_STRING_LEN];
    char *pos;
    char temp[MAX_STRING_LEN];
    strcpy(temp, s);

    // 간단한 구현: 첫 번째 발생만 치환
    pos = strstr(temp, find);
    if (pos == NULL) {
        strcpy(result, temp);
    } else {
        int len = pos - temp;
        strncpy(result, temp, len);
        result[len] = '\0';
        strcat(result, replace_str);
        strcat(result, pos + strlen(find));
    }

    return result;
}

// ============================================================================
// 7. 문자열 반복
// ============================================================================

// 문자열 반복
char *string_repeat(const char *s, int count) {
    static char result[MAX_STRING_LEN];
    result[0] = '\0';

    for (int i = 0; i < count; i++) {
        strcat(result, s);
    }

    return result;
}

// ============================================================================
// 8. 통합 테스트
// ============================================================================

int test_string_operations(void) {
    // 기본 연산
    if (string_length("Hello") != 5) return 0;
    if (!string_equals(string_concat("Hello", " World"), "Hello World")) return 0;
    if (!string_is_empty("")) return 0;

    // 부분 추출
    if (!string_equals(string_substring("Hello", 0, 5), "Hello")) return 0;
    if (!string_equals(string_char_at("Hello", 0), "H")) return 0;

    // 검색
    if (!string_contains("Hello", "ell")) return 0;
    if (string_index_of("Hello", "e") != 1) return 0;
    if (!string_starts_with("Hello", "He")) return 0;
    if (!string_ends_with("Hello", "o")) return 0;

    // 변환
    if (!string_equals(string_to_upper("hello"), "HELLO")) return 0;
    if (!string_equals(string_to_lower("HELLO"), "hello")) return 0;
    if (!string_equals(string_trim("  hello  "), "hello")) return 0;

    // 분할
    char *parts[10];
    int count = string_split("a,b,c", ",", parts);
    if (count != 3) {
        for (int i = 0; i < count; i++) free(parts[i]);
        return 0;
    }
    for (int i = 0; i < count; i++) free(parts[i]);

    // 치환
    if (!string_equals(string_replace("hello world", "world", "there"), "hello there"))
        return 0;

    // 반복
    if (!string_equals(string_repeat("ab", 3), "ababab")) return 0;

    return 1;
}

int main(void) {
    printf("╔════════════════════════════════════════════╗\n");
    printf("║      String Operations - C Version        ║\n");
    printf("╚════════════════════════════════════════════╝\n");
    printf("\n");

    printf("Basic Operations:\n");
    printf("  length(\"Hello\") = %d\n", string_length("Hello"));
