    printf("  indexOf(\"Hello\", \"e\") = %d\n", string_index_of("Hello", "e"));
    printf("  startsWith(\"Hello\", \"He\") = %d\n", string_starts_with("Hello", "He"));
    printf("  endsWith(\"Hello\", \"o\") = %d\n", string_ends_with("Hello", "o"));
    printf("\n");

    printf("Transform Operations:\n");
    printf("  toUpper(\"hello\") = %s\n", string_to_upper("hello"));
    printf("  toLower(\"HELLO\") = %s\n", string_to_lower("HELLO"));
